```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque
from math import inf

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _reconstruct_path(prev: Dict[int, Optional[int]], source: int, target: int) -> List[int]:
    if source == target:
        return [source]
    if target not in prev:
        return []
    path: List[int] = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        if cur == source:
            break
        cur = prev.get(cur)
    if not path or path[-1] != source:
        return []
    path.reverse()
    return path


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
    stop_after_k_settled: Optional[int] = None,  # counts settled nodes excluding source
) -> Tuple[Dict[int, float], Dict[int, Optional[int]], List[int]]:
    """
    Dijkstra using a binary heap.
    Returns (dist, prev, settled_order_excluding_source).

    Complexity: O((V+E) log V) for full run.
    Note: assumes non-negative edge weights for correctness (as standard Dijkstra).
    """
    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    heap: List[Tuple[float, int]] = [(0.0, source)]
    settled: Set[int] = set()
    settled_order_excl_source: List[int] = []

    while heap:
        d_u, u = heapq.heappop(heap)
        if u in settled:
            continue
        settled.add(u)

        if u != source:
            settled_order_excl_source.append(u)
            if stop_after_k_settled is not None and len(settled_order_excl_source) >= stop_after_k_settled:
                # Once a node is popped (settled), its shortest distance is final.
                break

        if target is not None and u == target:
            break

        for v, w in graph.neighbors(u):
            nd = d_u + w
            if nd < dist.get(v, inf):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev, settled_order_excl_source


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V+E) log V) using Dijkstra + binary heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev, _ = _dijkstra(graph, source, target=target)

    if target not in dist:
        return None, []

    path = _reconstruct_path(prev, source, target)
    if not path:
        return None, []
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Complexity: O((V+E) log V) for the Dijkstra pass, plus output-size path materialization.
    """
    if source not in graph.nodes:
        return {}

    dist, prev, _ = _dijkstra(graph, source)

    # Build paths with memoization to avoid repeated backtracking work.
    path_cache: Dict[int, List[int]] = {source: [source]}

    def build_path(n: int) -> List[int]:
        if n in path_cache:
            return path_cache[n]
        p = prev.get(n)
        if p is None:
            return []
        pp = build_path(p)
        if not pp:
            return []
        path_cache[n] = pp + [n]
        return path_cache[n]

    result: Dict[int, Tuple[float, List[int]]] = {}
    for n, d in dist.items():
        if n == source:
            result[n] = (0.0, [source])
        else:
            p = build_path(n)
            if p:
                result[n] = (d, p)
    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Complexity: Early-termination Dijkstra.
    """
    if k <= 0:
        return []
    if source not in graph.nodes:
        return []

    dist, _, settled_order = _dijkstra(graph, source, stop_after_k_settled=k)

    # settled_order is already in non-decreasing distance order (Dijkstra pop order)
    out: List[Tuple[int, float]] = []
    for n in settled_order:
        if n in dist:  # should always be true for settled nodes
            out.append((n, dist[n]))
        if len(out) >= k:
            break
    return out


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E) using BFS (ignores weights).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    q = deque([source])
    seen = {source}
    while q:
        u = q.popleft()
        for v, _w in graph.neighbors(u):
            if v == target:
                return True
            if v not in seen:
                seen.add(v)
                q.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Complexity: O(V + E) using BFS over an undirected view of the graph.
    """
    nodes = graph.nodes
    if not nodes:
        return []

    # Build undirected adjacency in O(V+E).
    undirected: Dict[int, List[int]] = {n: [] for n in nodes}
    for u in nodes:
        for v, _w in graph.neighbors(u):
            undirected[u].append(v)
            undirected.setdefault(v, []).append(u)  # v is already in nodes, but keep safe.

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for start in nodes:
        if start in visited:
            continue
        comp: Set[int] = set()
        q = deque([start])
        visited.add(start)

        while q:
            u = q.popleft()
            comp.add(u)
            for v in undirected.get(u, []):
                if v not in visited:
                    visited.add(v)
                    q.append(v)

        components.append(comp)

    return components
